x = 3
l, r = 0, len(a)
while l < r:
    m = (l + r) // 2
    if a[m] < x:
        l = m + 1
    else:
        r = m
print(l)

a, k = [2, 3], 5
l, r = 0, min(a) * k
while l < r:
    m = (l + r) // 2
    if sum(m // x for x in a) >= k:
        r = m
    else:
        l = m + 1
print(l)

