advanced.solutionCode:
n, k = map(int, input().split())
a = list(map(int, input().split()))
l, r = 0, min(a) * k
while l < r:
    m = (l + r) // 2
    total = 0
    for x in a:
        total += m // x
        if total >= k:
            break
    if total >= k:
        r = m
    else:
        l = m + 1
print(l)
